// Ported from the public AIcss React source.
// Source: https://www.aicss.dev/components/file-diff
"use client"

import styles from "./file-diff.module.css";

const ROWS = [
  { old: 12, cur: 12, type: "ctx", text: "export function getToken() {" },
  { old: 13, cur: null, type: "del", text: "  return localStorage.token;" },
  { old: null, cur: 13, type: "add", text: '  const t = cookies.get("session");' },
  { old: null, cur: 14, type: "add", text: '  if (!t) throw new Error("no session");' },
  { old: null, cur: 15, type: "add", text: "  return t;" },
  { old: 14, cur: 16, type: "ctx", text: "}" },
];

export function FileDiff({ file = "src/auth.ts", rows = ROWS }) {
  const added = rows.filter((r) => r.type === "add").length;
  const removed = rows.filter((r) => r.type === "del").length;
  return (
    <div className={styles.diff}>
      <div className={styles.diffHead}>
        <span className={styles.diffFileWrap}>
          <svg className={styles.diffIcon} viewBox="0 0 24 24" width="15" height="15" aria-hidden="true">
            <path d="M17.25 6.75 22.5 12l-5.25 5.25m-10.5 0L1.5 12l5.25-5.25m7.5-3-4.5 16.5" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" />
          </svg>
          <span className={styles.diffFile}>{file}</span>
        </span>
        <span className={styles.diffStat}>
          <span className={styles.add}>+{added}</span>
          <span className={styles.del}>-{removed}</span>
        </span>
      </div>
      <div className={styles.diffBody}>
        {rows.map((r, i) => (
          <div key={i} className={styles.diffRow + " " + styles[r.type]}>
            <span className={styles.ln + " " + styles.old}>{r.old ?? ""}</span>
            <span className={styles.ln + " " + styles.new}>{r.cur ?? ""}</span>
            <span className={styles.sign}>
              {r.type === "add" ? "+" : r.type === "del" ? "-" : ""}
            </span>
            <code>{r.text}</code>
          </div>
        ))}
      </div>
    </div>
  );
}

/* Ported from https://www.aicss.dev/components/file-diff */
.diff { border-radius: 0.75rem; background: var(--card); box-shadow: 0 0.0625rem 0.125rem oklch(0 0 0 / 0.05), 0 0.125rem 0.25rem oklch(0 0 0 / 0.02), 0 0 0 0.03125rem oklch(0 0 0 / 0.08); padding: 0.75rem 1rem 1rem; overflow: hidden; font-family: ui-monospace, "SF Mono", Menlo, monospace; }
.diffHead {
  display: flex; align-items: center; gap: 0.5rem;
  margin: -0.75rem -1rem 0; padding: 0.625rem 0.75rem 0.625rem 1rem;
  background: transparent; border-bottom: 0.03125rem solid var(--border); font-size: 0.78125rem;
}
.diffFileWrap { display: inline-flex; align-items: center; gap: 0.4375rem; }
.diffIcon { display: block; width: 0.9375rem; height: 0.9375rem; color: var(--muted-foreground); flex: none; }
.diffFile { color: var(--foreground); line-height: 1; }
.diffStat { margin-left: auto; display: inline-flex; align-items: center; gap: 0.5rem; font-size: 0.75rem; line-height: 1; }
.diffStat .add { color: oklch(0.6247 0.137 159.8934); }
.diffStat .del { color: oklch(0.5771 0.2152 27.325); }
.diffBody {
  position: relative;
  margin: 0 -1rem -1rem; overflow: hidden;
  padding: 0.25rem 0; font-size: 0.78125rem; line-height: 1.25rem;
}
/* full-height gutter divider at the line-number edge (32px + 32px), unaffected
   by the body padding; z-index keeps it above the tinted add/del rows */
.diffBody::before { content: ""; position: absolute; top: 0; bottom: 0; left: 4rem; width: 0.03125rem; background: var(--border); z-index: 1; }
.diffRow {
  position: relative;
  display: grid; grid-template-columns: 2rem 2rem 1.125rem 1fr; align-items: stretch;
}
.diffRow .ln, .diffRow .sign { user-select: none; color: var(--muted-foreground); font-size: 0.6875rem; }
.diffRow .ln { text-align: right; padding: 0 0.4375rem; }
.diffRow .sign { text-align: center; }
.diffRow code { white-space: pre; padding: 0 0.75rem 0 0.5rem; color: var(--muted-foreground); }
/* left accent bar: solid green for additions, red hatch for deletions */
.diffRow.add::before, .diffRow.del::before {
  content: ""; position: absolute; top: 0; bottom: 0; left: 0; width: 0.1875rem;
}
.diffRow.add::before { background: oklch(0.6247 0.137 159.8934); }
.diffRow.del::before {
  background: repeating-linear-gradient(45deg, oklch(0.5771 0.2152 27.325) 0, oklch(0.5771 0.2152 27.325) 0.09375rem, transparent 0.09375rem, transparent 0.1875rem);
}
.diffRow.add { background: oklch(0.5244 0.1401 148.0394 / 0.09); }
.diffRow.add .sign, .diffRow.add .new { color: oklch(0.6247 0.137 159.8934); }
.diffRow.add code { color: var(--foreground); }
.diffRow.del { background: oklch(0.5517 0.2051 24.5252 / 0.09); }
.diffRow.del .sign, .diffRow.del .old { color: oklch(0.5771 0.2152 27.325); }
.diffRow.del code { color: var(--foreground); }
